SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('纯白の悲歌','绝望的服从者','自我认知障碍','致那年夏天消失的你','节目报幕-华彩古韵','节目报幕-山野回声','节目报幕-环游之旅','节目报幕-茶歇交响','花火のように','花爱如歌(feat.名取依白野)','花瓣向明日飘去','莉莉丝','萤火之语','葬花泪','蔚蓝深海','蛰','融雪','衔风与愿','补天裂','语言下空无一物','赏味期限','赏味期限-永夜minus','赫奇帕奇印象曲','赫奇帕奇印象曲·伴奏','跨越数千昼夜','逐光者','醉枕清风','重生','量产型机器人','金牛座','金陵叹','问心','阿兹卡班印象曲','雨季，窗边,你','霓虹燈 c') ORDER BY sm.title,sm.album_id